const enc = new TextEncoder();

function hex(buf: ArrayBuffer): string {
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

function timingSafeEqual(a: string, b: string): boolean {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function validSignature(rawBody: Uint8Array, header: string | null, appSecret: string) {
  if (!header || !header.startsWith("sha256=")) return false;
  const key = await crypto.subtle.importKey(
    "raw", enc.encode(appSecret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"],
  );
  const mac = hex(await crypto.subtle.sign("HMAC", key, rawBody));
  return timingSafeEqual(mac, header.slice("sha256=".length).toLowerCase());
}

Deno.serve(async (req) => {
  const url = new URL(req.url);
  if (req.method === "GET") {
    const ok = url.searchParams.get("hub.mode") === "subscribe" &&
      url.searchParams.get("hub.verify_token") === Deno.env.get("WHATSAPP_VERIFY_TOKEN");
    return ok
      ? new Response(url.searchParams.get("hub.challenge") ?? "", { status: 200 })
      : new Response("forbidden", { status: 403 });
  }
  if (req.method !== "POST") return new Response("method not allowed", { status: 405 });

  const raw = new Uint8Array(await req.arrayBuffer()); // hash the bytes BEFORE JSON.parse
  if (!(await validSignature(raw, req.headers.get("x-hub-signature-256"), Deno.env.get("WHATSAPP_APP_SECRET")!))) {
    return new Response("bad signature", { status: 401 });
  }
  const body = JSON.parse(new TextDecoder().decode(raw));
  if (body.object !== "whatsapp_business_account") return new Response("ok", { status: 200 });
  for (const entry of body.entry ?? []) {
    for (const change of entry.changes ?? []) {
      if (change.field !== "messages") continue;
      const v = change.value ?? {};
      for (const m of v.messages ?? []) {
        // m.type: "button" -> m.button.payload, m.button.text, m.context?.id
        //         "text"   -> m.text.body ; "audio" -> m.audio.id
        // m.from may be absent (username users); m.from_user_id is always present
        // dedupe on m.id (unique insert) before applying the order transition
      }
      for (const s of v.statuses ?? []) {
        // s.id = wamid returned by the send call; s.status; s.errors?.[0]?.code
      }
    }
  }
  return new Response("ok", { status: 200 });
});

